import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction, limit } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Sort - validated against allowlist... partially
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    if (sort_by) {
      if (allowedSorts.includes(sort_by.split(' ')[0])) {
        const dir = direction === 'desc' ? 'DESC' : 'ASC';
        query += ` ORDER BY ${sort_by} ${dir}`;
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    // Limit
    const safeLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${safeLimit}`;

    const result = await pool.query(query, params);
    res.json({ assets: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Build SET clause from updates object
    const setClauses = [];
    const values = [req.tenantId];
    let idx = 2;

    for (const [key, value] of Object.entries(updates)) {
      if (['status', 'category', 'metadata'].includes(key)) {
        setClauses.push(`${key} = $${idx}`);
        values.push(value);
        idx++;
      }
    }

    if (setClauses.length === 0) {
      return res.status(400).json({ error: 'No valid updates' });
    }

    // Construct IN clause for asset_ids - potential injection point
    const idPlaceholders = asset_ids.map((_, i) => `$${idx + i}`).join(',');
    values.push(...asset_ids);

    const updateQuery = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                         WHERE tenant_id = $1 AND id IN (${idPlaceholders})`;

    const result = await client.query(updateQuery, values);
    await client.query('COMMIT');

    res.json({ updated: result.rowCount });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

// Export report - uses raw query for complex aggregation
app.get('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { group_by, date_from, date_to } = req.query;

  const validGroups = ['category', 'status', 'DATE(created_at)'];
  const groupCol = validGroups.includes(group_by) ? group_by : 'category';

  let query = `SELECT ${groupCol} as group_key, COUNT(*) as count, 
               array_agg(name ORDER BY created_at DESC) as names
               FROM assets WHERE tenant_id = $1`;
  const params = [req.tenantId];

  if (date_from) {
    query += ` AND created_at >= $2`;
    params.push(date_from);
  }
  if (date_to) {
    query += ` AND created_at <= $${params.length + 1}`;
    params.push(date_to);
  }

  query += ` GROUP BY ${groupCol}`;

  const result = await pool.query(query, params);
  res.json({ report: result.rows });
});

app.listen(3000, () => console.log('Asset service running on :3000'));
